// Repro for uart_tx: a start pulse while a frame is in flight must be ignored,
// so the transmitted byte must be the one latched when the frame began.
// Expected values come from the specified behaviour (8N1, LSB first,
// start-while-busy ignored), not from any implementation's output.
`timescale 1ns / 1ps
module uart_tx_reload_repro_tb;
    localparam integer CPB        = 4;
    localparam integer CLK_PERIOD = 10;
    localparam integer BIT_NS     = CPB * CLK_PERIOD;
    localparam [7:0]   FIRST      = 8'hA5;
    localparam [7:0]   SECOND     = 8'h3C;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #(CLK_PERIOD / 2) clk = ~clk;

    reg [8*128-1:0] nonce;
    integer passed   = 0;
    integer failed   = 0;
    reg     finished = 1'b0;
    reg [7:0] rx;
    reg       idle_ok;
    integer   i;

    task check;
        input              cond;
        input [8*64-1:0]   what;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("PASS: %0s", what);
            end else begin
                failed = failed + 1;
                $display("FAIL: %0s", what);
            end
        end
    endtask

    task report;
        begin
            if (!finished) begin
                finished = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    initial begin
        nonce = "missing";
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
            if (!$value$plusargs("nonce=%s", nonce))
                if (!$value$plusargs("NONCE=%s", nonce))
                    nonce = "missing";

        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);

        fork
            begin : receiver
                @(negedge tx);
                #(BIT_NS / 2);
                check(tx == 1'b0, "start bit is low");
                for (i = 0; i < 8; i = i + 1) begin
                    #(BIT_NS);
                    rx[i] = tx;
                end
                #(BIT_NS);
                check(tx == 1'b1, "stop bit is high");
                $display("INFO: received 8'h%02h, expected 8'h%02h", rx, FIRST);
                check(rx == FIRST, "byte unchanged by start pulse while busy");
            end
            begin : stimulus
                @(negedge clk);
                data  = FIRST;
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
                data  = 8'd0;
                // Into data bit 1 of the first frame: pulse start with another byte.
                repeat (2 * CPB + 1) @(negedge clk);
                data  = SECOND;
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
                data  = 8'd0;
            end
        join

        // After the frame: the ignored start must not produce a second frame.
        idle_ok = 1'b1;
        repeat (4 * CPB) begin
            @(negedge clk);
            if (tx !== 1'b1) idle_ok = 1'b0;
        end
        check(idle_ok && (busy == 1'b0), "line idle and not busy after the frame");

        report;
    end

    initial begin : watchdog
        #(20000);
        if (!finished) begin
            failed = failed + 1;
            $display("FAIL: timeout waiting for frame");
            report;
        end
    end
endmodule
=== END FILE ===

