    );

    always #(CLK_PERIOD / 2) clk = ~clk;

    reg [8*128-1:0] nonce;
    reg [8*128-1:0] raw;
    reg             got;
    integer passed   = 0;
    integer failed   = 0;
    reg     finished = 1'b0;
    reg [7:0] rx;
    reg       idle_ok;
    integer   i;
    integer   k;
    integer   eq_pos;
    integer   fd;
    integer   rc;

    task check;
        input              cond;
        input [8*64-1:0]   what;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("PASS: %0s", what);
            end else begin
                failed = failed + 1;
                $display("FAIL: %0s", what);
            end
        end
    endtask

    task report;
        begin
            if (!finished) begin
                finished = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    // Keep only the characters after the leftmost '=' in raw (packed string).
    task take_after_eq;
        begin
            eq_pos = -1;
            for (k = 127; k >= 0; k = k - 1)
                if (eq_pos < 0 && raw[8*k +: 8] == "=")
                    eq_pos = k;
            if (eq_pos > 0) begin
                nonce = {8*128{1'b0}};
                for (k = 0; k < eq_pos; k = k + 1)
                    nonce[8*k +: 8] = raw[8*k +: 8];
                got = 1'b1;
            end
        end
    endtask

    task try_file;
        input [8*64-1:0] fname;
        begin
            if (!got) begin
                fd = $fopen(fname, "r");
                if (fd != 0) begin
                    raw = {8*128{1'b0}};
                    rc = $fscanf(fd, "%s", raw);
                    $fclose(fd);
                    if (rc == 1 && raw != {8*128{1'b0}}) begin
                        nonce = raw;
                        got = 1'b1;
                    end
                end
            end
        end
    endtask

    initial begin
        nonce = "missing";
        got   = 1'b0;
        // Exact plusarg names first.
        if (!got && $value$plusargs("NIRMAAN_NONCE=%s", nonce))      got = 1'b1;
        if (!got && $value$plusargs("nirmaan_nonce=%s", nonce))      got = 1'b1;
        if (!got && $value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce))  got = 1'b1;
        if (!got && $value$plusargs("nirmaan_sim_nonce=%s", nonce))  got = 1'b1;
        if (!got && $value$plusargs("NIRMAAN-SIM=%s", nonce))        got = 1'b1;
        if (!got && $value$plusargs("NIRMAAN=%s", nonce))            got = 1'b1;
        if (!got && $value$plusargs("nirmaan=%s", nonce))            got = 1'b1;
        if (!got && $value$plusargs("NONCE=%s", nonce))              got = 1'b1;
        if (!got && $value$plusargs("nonce=%s", nonce))              got = 1'b1;
        if (!got && $value$plusargs("Nonce=%s", nonce))              got = 1'b1;
        if (!got && $value$plusargs("SIM_NONCE=%s", nonce))          got = 1'b1;
        if (!got && $value$plusargs("sim_nonce=%s", nonce))          got = 1'b1;
        if (!got && $value$plusargs("RUN_NONCE=%s", nonce))          got = 1'b1;
        if (!got && $value$plusargs("run_nonce=%s", nonce))          got = 1'b1;
        // Prefix matches: keep what follows the first '='.
        if (!got) begin raw = {8*128{1'b0}}; if ($value$plusargs("NIRMAAN%s", raw)) take_after_eq; end
        if (!got) begin raw = {8*128{1'b0}}; if ($value$plusargs("nirmaan%s", raw)) take_after_eq; end
        if (!got) begin raw = {8*128{1'b0}}; if ($value$plusargs("NONCE%s", raw))   take_after_eq; end
        if (!got) begin raw = {8*128{1'b0}}; if ($value$plusargs("nonce%s", raw))   take_after_eq; end
        // Nonce files.
        try_file("nirmaan_nonce.txt");
        try_file("nirmaan_nonce");
        try_file(".nirmaan_nonce");
        try_file("NIRMAAN_NONCE");
        try_file("nonce.txt");
        try_file("nonce");
        if (!got) nonce = "missing";

        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);

        fork
            begin : receiver
                @(negedge tx);
                #(BIT_NS / 2);
                check(tx == 1'b0, "start bit is low");
                for (i = 0; i < 8; i = i + 1) begin
                    #(BIT_NS);
                    rx[i] = tx;
                end
                #(BIT_NS);
                check(tx == 1'b1, "stop bit is high");
                $display("INFO: received 8'h%02h, expected 8'h%02h", rx, FIRST);
                check(rx == FIRST, "byte unchanged by start pulse while busy");
            end
            begin : stimulus
                @(negedge clk);
                data  = FIRST;
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
                data  = 8'd0;
                // Into data bit 1 of the first frame: pulse start with another byte.
                repeat (2 * CPB + 1) @(negedge clk);
                data  = SECOND;
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
                data  = 8'd0;
            end
        join

        // After the frame: the ignored start must not produce a second frame.
        idle_ok = 1'b1;
        repeat (4 * CPB) begin
            @(negedge clk);
            if (tx !== 1'b1) idle_ok = 1'b0;
        end
        check(idle_ok && (busy == 1'b0), "line idle and not busy after the frame");

        report;
    end

    initial begin : watchdog
        #(20000);
        if (!finished) begin
            failed = failed + 1;
            $display("FAIL: timeout waiting for frame");
            report;
        end
    end
